// === Tab: mySketch ===
var n, tam, maxtam;
n = 7;
var rx = [],
	ry = [],
	rz = [];
var esp = 10;
var rodar = false;

function setup() {
	tam = [window.innerWidth, window.innerHeight];
	maxtam = min(...tam);
	d = maxtam / 2 / n / sqrt(2);

	createCanvas(tam[0], tam[1], WEBGL);
	angleMode(DEGREES);
	strokeWeight(2);

	for (let i = 0; i < esp * n; i++) {
		rz[i] = 0;
		rx[i] = 0;
		ry[i] = 0;
	}
}

function draw() {
	let aux = clique * 255;
	background(aux);
	fill(aux, aux, aux, 255 / n * 1.5)
	stroke(!clique * 255);

	orbitControl();

	if (!rodar) {
		if (rotationX * rotationY * rotationZ != 0 && rotationX * rotationY * rotationZ != null) {
			rodar = true;
		}
	}

	for (let i = esp * n; i > 0; i--) {
		rz[i] = rz[i - 1];
		rx[i] = rx[i - 1];
		ry[i] = ry[i - 1];
	}

	if (rodar) {
		rz[0] = rotationZ;
		rx[0] = rotationX;
		ry[0] = rotationY;
	} else {
		ry[0] = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, tam[0], 0, -360);
		rx[0] = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, tam[1], 0, -180);
	}


	for (let i = 0; i < n; i++) {

		if (!i) {
			push();
			rotateZ(rz[esp * i]);
			rotateX(rx[esp * i]);
			rotateY(ry[esp * i]);
			box(2 * d);
			pop();
		} else {
			push();
			rotateZ(rz[esp * i]);
			rotateX(rx[esp * i]);
			rotateY(ry[esp * i]);

			let ad = (i + 1) * d * abs(cos(frameCount)) + d;

			beginShape();
			vertex(-d, -d, ad);
			vertex(-d, d, ad);
			vertex(d, d, ad);
			vertex(d, -d, ad);
			endShape(CLOSE);

			beginShape();
			vertex(-d, -d, -ad);
			vertex(-d, d, -ad);
			vertex(d, d, -ad);
			vertex(d, -d, -ad);
			endShape(CLOSE);

			beginShape();
			vertex(ad, -d, -d);
			vertex(ad, -d, d);
			vertex(ad, d, d);
			vertex(ad, d, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-ad, -d, -d);
			vertex(-ad, -d, d);
			vertex(-ad, d, d);
			vertex(-ad, d, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-d, ad, -d);
			vertex(-d, ad, d);
			vertex(d, ad, d);
			vertex(d, ad, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-d, -ad, -d);
			vertex(-d, -ad, d);
			vertex(d, -ad, d);
			vertex(d, -ad, -d);
			endShape(CLOSE);

			pop();
		}
	}

}

clique = true;

function mouseClicked() {
	clique = !clique;
}
